package com.lagradost.cloudstream3.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Centralized Solar Icons mapping system for Compose UI across CloudStream.
 * Uses authentic 24x24 Solar Icons (Outline and Bold weights).
 */
object AppIcons {
    val Default: AppIcons get() = this
    val Filled: AppIcons get() = this
    val Outlined: AppIcons get() = this
    val Rounded: AppIcons get() = this
    val AutoMirrored: AppIcons get() = this

    private data class SolarPath(
        val pathData: String,
        val fillType: PathFillType = PathFillType.NonZero,
    )

    private fun solarIcon(
        name: String,
        vararg paths: SolarPath,
    ): ImageVector = buildSolarIcon(name = name, autoMirror = false, paths = paths)

    private fun mirroredSolarIcon(
        name: String,
        vararg paths: SolarPath,
    ): ImageVector = buildSolarIcon(name = name, autoMirror = true, paths = paths)

    private fun buildSolarIcon(
        name: String,
        autoMirror: Boolean,
        vararg paths: SolarPath,
    ): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
            autoMirror = autoMirror,
        )
        for (p in paths) {
            builder.addPath(
                pathData = addPathNodes(p.pathData),
                pathFillType = p.fillType,
                fill = SolidColor(Color.White),
                stroke = null,
                strokeLineWidth = 1f,
                strokeLineCap = StrokeCap.Butt,
                strokeLineJoin = StrokeJoin.Bevel,
                strokeLineMiter = 1f,
            )
        }
        return builder.build()
    }

